(function(root){'use strict';
const A=root.MT_ANALYSIS,D=root.MT_ANALYSIS_ADAPTER,W=root.MT_WORKSPACE,E=root.MT_STUDY_EXPORT,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>typeof v==='number'?v.toLocaleString('en-GB',{maximumSignificantDigits:7}):String(v??'—'),$=id=>document.getElementById(id);
const panel=document.createElement('details');panel.className='panel study-analysis';panel.id='study-analysis';panel.innerHTML='<summary>Save, compare & analyse this experiment</summary><div id="study-analysis-body"></div><p id="study-analysis-status" role="status"></p>';document.querySelector('main').append(panel);let active=null,captures={a:null,b:null},cancelled=false,heatRows=null;
function status(s){$('study-analysis-status').textContent=s;}
function action(id,fn){$(id)?.addEventListener('click',()=>Promise.resolve().then(fn).catch(e=>status(e.message)));}
function options(rows){return rows.map(([k,t])=>'<option value="'+esc(k)+'">'+esc(t)+'</option>').join('');}
function table(headers,rows){return '<div class="table-wrap" tabindex="0" role="region" aria-label="Analysis data"><table><thead><tr>'+headers.map(v=>'<th scope="col">'+esc(v)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((v,i)=>'<'+(i?'td':'th scope="row"')+'>'+esc(fmt(v))+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function chart(curve){const points=curve.series.flatMap(s=>s.points),xs=points.map(p=>p.x),ys=points.map(p=>p.y);let minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);if(minX===maxX){minX-=.5;maxX+=.5;}if(minY===maxY){minY-=.5;maxY+=.5;}const X=v=>100+650*(v-minX)/(maxX-minX),Y=v=>320-270*(v-minY)/(maxY-minY),colors=['#69d5ed','#f8ce81','#cfadff','#86e6b0'];return '<svg viewBox="0 0 800 420" role="img" aria-label="A solid and B dashed on common numerical axes"><title>A/B scenario comparison</title>'+Array.from({length:5},(_,i)=>{const x=minX+(maxX-minX)*i/4,y=minY+(maxY-minY)*i/4;return '<path d="M'+X(x)+' 50V320 M100 '+Y(y)+'H750" stroke="#627483" stroke-width=".5"/><text x="'+X(x)+'" y="345" fill="currentColor" text-anchor="middle">'+esc(fmt(x))+'</text><text x="90" y="'+(Y(y)+4)+'" fill="currentColor" text-anchor="end">'+esc(fmt(y))+'</text>';}).join('')+curve.series.map((s,i)=>'<polyline fill="none" stroke="'+colors[(i%(curve.series.length/2))%colors.length]+'" stroke-width="2.5"'+(s.dashed?' stroke-dasharray="8 5"':'')+' points="'+s.points.map(p=>X(p.x)+','+Y(p.y)).join(' ')+'"/>').join('')+'<text x="425" y="385" fill="currentColor" text-anchor="middle">'+esc(curve.xLabel)+'</text><text x="15" y="25" fill="currentColor">'+esc(curve.yLabel)+'</text></svg><p>'+curve.series.map(s=>esc(s.name)+(s.dashed?' · dashed':' · solid')).join(' | ')+'</p>';}
function key(){return 'mt.study.analysis.v1:'+active;}
function capture(){const ctx=D.capture();return {modelId:ctx.id,title:ctx.title,inputs:A.copy(ctx.inputs),evaluated:A.copy(D.evaluate(ctx.id,ctx.inputs)),at:Date.now()};}
function restore(){captures={a:null,b:null};try{const saved=JSON.parse(localStorage.getItem(key())||'null');if(saved?.version===1)for(const k of ['a','b']){const v=saved[k];if(v?.modelId===active&&v.inputs){const z=D.evaluate(active,v.inputs);captures[k]={...v,evaluated:z};}}}catch{status('A previous comparison could not be restored. The stored record is retained until you capture a new scenario.');}}
function persist(){try{localStorage.setItem(key(),JSON.stringify({version:1,...captures}));}catch{status('Comparison available for this session. Export it before closing.');}}
function compare(){const a=captures.a,b=captures.b;if(!a||!b){$('analysis-comparison').innerHTML='<p>Capture A, change the model, then capture B.</p>';return;}const metrics=[...new Set([...Object.keys(A.numeric(a.evaluated.results)),...Object.keys(A.numeric(b.evaluated.results))])],leavesA=A.leaves(a.inputs),leavesB=A.leaves(b.inputs),diff=leavesA.map(v=>{const other=leavesB.find(b=>b.key===v.key);return [v.key,v.value,other?.value,other?other.value-v.value:'Unavailable'];}).filter(v=>v[1]!==v[2]);$('analysis-comparison').innerHTML='<h3>Result comparison</h3>'+table(['Result','A','B','B − A'],metrics.map(k=>[k,a.evaluated.results[k],b.evaluated.results[k],typeof a.evaluated.results[k]==='number'&&typeof b.evaluated.results[k]==='number'?b.evaluated.results[k]-a.evaluated.results[k]:'Unavailable']))+'<h3>Changed numeric inputs</h3>'+table(['Input','A','B','Difference'],diff)+(JSON.stringify(a.inputs)!==JSON.stringify(b.inputs)&&!diff.length?'<p>Non-numeric settings differ; see the exported scenario inputs.</p>':'')+A.curves(a.evaluated,b.evaluated).map(chart).join('');}
function inputLabel(field){const input=document.querySelector('[name="'+CSS.escape(field.key)+'"]');return input?.closest('label')?.textContent.trim()||field.key;}
function show(){try{const ctx=D.capture();if(ctx.id===active&&$('analysis-save'))return;active=ctx.id;cancelled=true;restore();const store=W.create(localStorage),data=store.data,fields=A.leaves(ctx.inputs),metrics=ctx.metrics.filter(m=>!/residual/i.test(m.label));$('study-analysis-body').innerHTML='<h2>'+esc(ctx.title)+'</h2><section><h3>Save to a project</h3><div class="fields"><label>Project<select id="analysis-project">'+options(data.projects.map(p=>[p.id,p.title]))+'</select></label><label>Calculation title<input id="analysis-title" maxlength="200" value="'+esc(ctx.title)+'"></label></div><button type="button" id="analysis-save"'+(!data.projects.length?' disabled':'')+'>Save current inputs, results and diagrams</button><a href="../workspace.html#projects" target="_top">Manage projects →</a> <a href="../workspace.html#help?model='+esc(ctx.id)+'&chapter='+(root.MT_INTERACTIVE_MODULES.find(m=>m.id===ctx.id)?.chapter||1)+'" target="_top">Report a problem with this model →</a></section><section><h3>Scenario comparison</h3><div class="export-actions"><button type="button" id="capture-a">Capture A</button><button type="button" id="capture-b">Capture B</button><button type="button" id="analysis-export">Export comparison JSON</button></div><div id="analysis-comparison"></div></section><section><h3>Trace a quantity</h3><p>Choose an input to locate its control and show its current value alongside the diagram. The model equations and assumptions remain below the inputs.</p><div class="fields"><label>Input / symbol<select id="analysis-symbol">'+options(fields.map(f=>[f.key,inputLabel(f)]))+'</select></label><button type="button" id="analysis-highlight">Locate input and diagram annotation</button></div><p id="analysis-symbol-value" role="status"></p></section><section><h3>Local sensitivity</h3><p>Symmetric differences around the current inputs estimate the local slope. Elasticity is (input / result) × slope. Zero baselines have no relative elasticity. Discrete settings and points outside the model domain are reported separately.</p><div class="fields"><label>Result<select id="analysis-metric">'+options(metrics.map(m=>[m.id,m.id]))+'</select></label><label>Perturbation · %<input id="analysis-step" type="number" min=".01" max="25" step=".01" value="1"></label></div><button type="button" id="analysis-sensitivity">Rank local sensitivities</button><div id="analysis-ranking"></div></section><section><h3>Two-input map</h3><p>Each cell recalculates the model. Grey cells are outside its valid domain. Select a table row for the exact inputs and result.</p><div class="fields">'+['x','y'].map((axis,i)=>'<fieldset><legend>'+axis.toUpperCase()+' input</legend><label>Quantity<select id="heat-'+axis+'">'+options(fields.map(f=>[f.key,inputLabel(f)]))+'</select></label><label>Minimum<input type="number" step="any" id="heat-'+axis+'-min"></label><label>Maximum<input type="number" step="any" id="heat-'+axis+'-max"></label></fieldset>').join('')+'</div><div class="export-actions"><button type="button" id="heat-run">Calculate 20 × 20 map</button><button type="button" id="heat-cancel">Cancel</button><button type="button" id="heat-csv" disabled>Export all cells CSV</button></div><div id="heat-result"></div></section>';
compare();action('analysis-save',()=>{const snapshot=D.snapshot(),context=D.capture();store.saveCase($('analysis-project').value,$('analysis-title').value,context.id,snapshot,context.inputs);status('Current scenario saved to the project.');});for(const slot of ['a','b'])action('capture-'+slot,()=>{captures[slot]=capture();persist();compare();status('Scenario '+slot.toUpperCase()+' captured. Change the model inputs to explore another scenario.');});action('analysis-export',()=>{if(!captures.a||!captures.b)throw Error('Capture both scenarios first.');E.download('MarineTools-'+active+'-comparison.json',JSON.stringify({version:1,modelId:active,...captures},null,2),'application/json');});action('analysis-highlight',()=>{const ctx=D.capture(),leaf=A.leaves(ctx.inputs).find(v=>v.key===$('analysis-symbol').value);if(!leaf)throw Error('Choose a numeric input.');document.querySelectorAll('.analysis-linked').forEach(el=>el.classList.remove('analysis-linked'));const input=document.querySelector('[name="'+CSS.escape(leaf.key)+'"]');if(input){input.closest('details')?.setAttribute('open','');input.classList.add('analysis-linked');input.focus();}const text=inputLabel(leaf)+' = '+fmt(leaf.value);$('analysis-symbol-value').textContent=text;const svg=[...document.querySelectorAll('svg')].find(s=>!s.closest('#study-analysis')&&!s.hasAttribute('hidden'));if(svg){svg.querySelector('[data-analysis-annotation]')?.remove();const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.dataset.analysisAnnotation='true';t.setAttribute('x','100');t.setAttribute('y','20');t.setAttribute('fill','currentColor');t.textContent=text;svg.append(t);svg.classList.add('analysis-linked');}const key=leaf.key.split('.').at(-1);for(const note of document.querySelectorAll('#model-notes li,#notes p,[data-symbol]'))if(new RegExp('(^|[^a-zA-Z])'+key+'([^a-zA-Z]|$)','i').test(note.textContent))note.classList.add('analysis-linked');});action('analysis-sensitivity',()=>{const ctx=D.capture(),rows=A.sensitivity(x=>D.evaluate(ctx.id,x),ctx.inputs,$('analysis-metric').value,Number($('analysis-step').value)/100);$('analysis-ranking').innerHTML=table(['Input','Baseline','± step','Slope','Elasticity','Domain check'],rows.map(r=>[r.key,r.baseline,r.step,r.slope,r.elasticity,r.error||'Valid local difference']));});
function range(axis){const f=fields.find(f=>f.key===$('heat-'+axis).value);if(!f)return;const step=Math.abs(f.value)*.2||1;$('heat-'+axis+'-min').value=String(f.value-step);$('heat-'+axis+'-max').value=String(f.value+step);}$('heat-y').selectedIndex=Math.min(1,fields.length-1);for(const axis of ['x','y']){$('heat-'+axis).onchange=()=>range(axis);range(axis);}action('heat-cancel',()=>{cancelled=true;status('Cancellation requested.');});action('heat-run',async()=>{cancelled=false;heatRows=null;$('heat-csv').disabled=true;$('heat-run').disabled=true;const ctx=D.capture(),metric=$('analysis-metric').value,axes=['x','y'].map(axis=>({path:fields.find(f=>f.key===$('heat-'+axis).value).path,min:Number($('heat-'+axis+'-min').value),max:Number($('heat-'+axis+'-max').value)})),id=active;try{status('Calculating 400 cells…');const rows=await A.heatmap(x=>D.evaluate(ctx.id,x),ctx.inputs,metric,...axes,{cancel:()=>cancelled||active!==id||!panel.isConnected});if(active!==id)return;heatRows=rows;const valid=rows.filter(v=>v.value!==null),min=valid.length?Math.min(...valid.map(v=>v.value)):0,max=valid.length?Math.max(...valid.map(v=>v.value)):0;$('heat-result').innerHTML='<h4>'+esc(metric)+'</h4><svg viewBox="0 0 600 460" role="img" aria-label="Two input heatmap, exact values in table"><title>'+esc(metric)+'</title>'+rows.map((r,i)=>'<rect x="'+(65+(i%20)*23)+'" y="'+(410-Math.floor(i/20)*19)+'" width="23" height="19" fill="'+(r.value===null?'#77818a':'hsl('+(220-200*(r.value-min)/(max-min||1))+' 75% 55%)')+'"><title>'+esc(r.error||fmt(r.x)+', '+fmt(r.y)+' → '+fmt(r.value))+'</title></rect>').join('')+'<text x="65" y="455" fill="currentColor">X: '+esc($('heat-x').selectedOptions[0].textContent)+'</text><text x="65" y="25" fill="currentColor">Y: '+esc($('heat-y').selectedOptions[0].textContent)+'</text></svg><p>'+valid.length+' valid cells, '+(rows.length-valid.length)+' outside model domain. Colour scale: '+esc(fmt(min))+' to '+esc(fmt(max))+'.</p><details><summary>All numerical cells and domain messages</summary>'+table(['X input','Y input',metric,'Domain'],rows.map(r=>[r.x,r.y,r.value,r.error||'Valid']))+'</details>';$('heat-csv').disabled=false;status('Heatmap calculated from the captured inputs.');}finally{$('heat-run').disabled=false;}});action('heat-csv',()=>{if(!heatRows)throw Error('Calculate a map first.');E.download('MarineTools-'+active+'-heatmap.csv',E.csv([['X','Y','Value','Domain'],...heatRows.map(r=>[r.x,r.y,r.value,r.error||'Valid'])]),'text/csv');});
}catch(e){status(e.message);}}
panel.addEventListener('toggle',()=>{if(panel.open)show();});window.addEventListener('hashchange',()=>{cancelled=true;active=null;if(panel.open)setTimeout(show,0);});window.addEventListener('pagehide',()=>{cancelled=true;});root.MT_NEXT_ANALYSIS_UI={show,capture,chart};
})(window);
